     9→import Combine
    10→import SwiftUI
    11→
    12→typealias SessionVerificationViewModelType = StateStoreViewModel<SessionVerificationScreenViewState, SessionVerificationScreenViewAction>
    13→
    14→class SessionVerificationScreenViewModel: SessionVerificationViewModelType, SessionVerificationScreenViewModelProtocol {
    15→    private let sessionVerificationControllerProxy: SessionVerificationControllerProxyProtocol
    16→    private let flow: SessionVerificationScreenFlow
    17→    
    18→    private var stateMachine: SessionVerificationScreenStateMachine
    19→
    20→    private var actionsSubject: PassthroughSubject<SessionVerificationScreenViewModelAction, Never> = .init()
    21→    
    22→    var actions: AnyPublisher<SessionVerificationScreenViewModelAction, Never> {
    23→        actionsSubject.eraseToAnyPublisher()
    24→    }
    25→
    26→    init(sessionVerificationControllerProxy: SessionVerificationControllerProxyProtocol,
    27→         flow: SessionVerificationScreenFlow,
    28→         appSettings: AppSettings,
    29→         mediaProvider: MediaProviderProtocol,
    30→         verificationState: SessionVerificationScreenStateMachine.State = .initial) {
    31→        self.sessionVerificationControllerProxy = sessionVerificationControllerProxy
    32→        self.flow = flow
    33→        
    34→        stateMachine = SessionVerificationScreenStateMachine(state: verificationState)
    35→        
    36→        super.init(initialViewState: .init(flow: flow,
    37→                                           learnMoreURL: appSettings.encryptionURL,
    38→                                           verificationState: verificationState),
    39→                   mediaProvider: mediaProvider)
    40→        
    41→        setupStateMachine()
    42→        
    43→        sessionVerificationControllerProxy.actions
    44→            .receive(on: DispatchQueue.main)
    45→            .sink { [weak self] callback in
    46→                guard let self else { return }
    47→                
    48→                switch callback {
    49→                case .receivedVerificationRequest:
    50→                    break // Incoming verification requests are handled on the higher levels
    51→                case .acceptedVerificationRequest:
    52→                    self.stateMachine.processEvent(.didAcceptVerificationRequest)
    53→                case .startedSasVerification:
    54→                    self.stateMachine.processEvent(.didStartSasVerification)
    55→                case .receivedVerificationData(let emojis):
    56→                    guard self.stateMachine.state == .sasVerificationStarted else {
    57→                        MXLog.warning("Callbacks: Ignoring receivedVerificationData due to invalid state.")
    58→                        return
    59→                    }
    60→                    
    61→                    self.stateMachine.processEvent(.didReceiveChallenge(emojis: emojis))
    62→                case .finished:
    63→                    self.stateMachine.processEvent(.didAcceptChallenge)
    64→                case .cancelled:
    65→                    self.stateMachine.processEvent(.didCancel)
    66→                case .failed:
    67→                    self.stateMachine.processEvent(.didFail)
    68→                }
    69→            }
    70→            .store(in: &cancellables)
    71→        
    72→        switch flow {
    73→        case .deviceResponder(let details), .userResponder(let details):
    74→            Task {
    75→                await self.sessionVerificationControllerProxy.acknowledgeVerificationRequest(details: details)
    76→            }
    77→        default:
    78→            break
    79→        }
    80→    }
    81→    
    82→    override func process(viewAction: SessionVerificationScreenViewAction) {
    83→        switch viewAction {
    84→        case .acceptVerificationRequest:
    85→            stateMachine.processEvent(.acceptVerificationRequest)
    86→        case .ignoreVerificationRequest:
    87→            actionsSubject.send(.finished)
    88→        case .requestVerification:
    89→            stateMachine.processEvent(.requestVerification)
    90→        case .startSasVerification:
    91→            stateMachine.processEvent(.startSasVerification)
    92→        case .restart:
    93→            stateMachine.processEvent(.restart)
    94→        case .accept:
    95→            stateMachine.processEvent(.acceptChallenge)
    96→        case .decline:
    97→            stateMachine.processEvent(.declineChallenge)
    98→        case .cancel:
    99→            stateMachine.processEvent(.cancel)
   100→            actionsSubject.send(.finished)
   101→        case .done:
   102→            actionsSubject.send(.finished)
   103→        }
   104→    }
   105→    
   106→    func stop() {
   107→        switch stateMachine.state {
   108→        case .initial, .verified, .cancelled: // non-cancellable states
   109→            return
   110→        default:
   111→            stateMachine.processEvent(.cancel)
   112→        }
   113→    }
   114→    
   115→    // MARK: - Private
   116→    
   117→    private func setupStateMachine() {
   118→        stateMachine.addTransitionHandler { [weak self] context in
   119→            guard let self else { return }
   120→                
   121→            state.verificationState = context.toState
   122→            
   123→            switch (context.fromState, context.event, context.toState) {
   124→            case (.initial, .acceptVerificationRequest, .acceptingVerificationRequest):
   125→                acceptVerificationRequest()
   126→            case (.initial, .requestVerification, .requestingVerification):
   127→                Task {
   128→                    switch await self.requestVerification() {
   129→                    case .success:
   130→                        // Need to wait for the callback from the remote
   131→                        break
   132→                    case .failure:
   133→                        self.stateMachine.processEvent(.didFail)
   134→                    }
   135→                }
   136→            case (.verificationRequestAccepted, .startSasVerification, .startingSasVerification):
   137→                startSasVerification()
   138→            case (.showingChallenge, .acceptChallenge, .acceptingChallenge):
   139→                acceptChallenge()
   140→            case (.showingChallenge, .declineChallenge, .decliningChallenge):
   141→                declineChallenge()
   142→            case (_, .cancel, .cancelling):
   143→                cancelVerification()
   144→            case (_, _, .verified):
   145→                actionsSubject.send(.finished)
   146→            case (.initial, _, .cancelled):
   147→                switch flow {
   148→                case .deviceResponder, .userResponder:
   149→                    actionsSubject.send(.finished)
   150→                default:
   151→                    break
   152→                }
   153→            default:
   154→                break
   155→            }
   156→        }
   157→        
   158→        stateMachine.addErrorHandler { context in
   159→            MXLog.error("Failed transition with context: \(context)")
   160→        }
   161→    }
   162→    
   163→    private func acceptVerificationRequest() {
   164→        Task {
   165→            guard flow.isResponder else {
   166→                fatalError("Incorrect API usage.")
   167→            }
   168→            
   169→            switch await sessionVerificationControllerProxy.acceptVerificationRequest() {
   170→            case .success:
   171→                stateMachine.processEvent(.didAcceptVerificationRequest)
   172→            case .failure:
   173→                stateMachine.processEvent(.didFail)
   174→            }
   175→        }
   176→    }
   177→    
   178→    private func requestVerification() async -> Result<Void, SessionVerificationControllerProxyError> {
   179→        switch flow {
   180→        case .deviceInitiator:
   181→            return await sessionVerificationControllerProxy.requestDeviceVerification()
   182→        case .userInitiator(let userID):
   183→            return await sessionVerificationControllerProxy.requestUserVerification(userID)
   184→        default:
   185→            fatalError("Incorrect API usage.")
   186→        }
   187→    }
   188→    
   189→    private func cancelVerification() {
   190→        Task {
   191→            switch await sessionVerificationControllerProxy.cancelVerification() {
   192→            case .success:
   193→                stateMachine.processEvent(.didCancel)
   194→            case .failure:
   195→                stateMachine.processEvent(.didFail)
   196→            }
   197→        }
   198→    }
   199→    
   200→    private func startSasVerification() {
   201→        Task {
   202→            switch await sessionVerificationControllerProxy.startSasVerification() {
   203→            case .success:
   204→                // Need to wait for the callback from the remote
   205→                break
   206→            case .failure:
   207→                stateMachine.processEvent(.didFail)
   208→            }
   209→        }
   210→    }
   211→    
   212→    private func acceptChallenge() {
   213→        Task {
   214→            switch await sessionVerificationControllerProxy.approveVerification() {
   215→            case .success:
   216→                // Need to wait for the callback from the remote
   217→                break
   218→            case .failure:
   219→                stateMachine.processEvent(.didFail)
   220→            }
   221→        }
   222→    }
   223→    
   224→    private func declineChallenge() {
   225→        Task {
   226→            switch await sessionVerificationControllerProxy.declineVerification() {
   227→            case .success:
   228→                stateMachine.processEvent(.didCancel)
   229→            case .failure:
   230→                stateMachine.processEvent(.didFail)
   231→            }
   232→        }
   233→    }
   234→}
