     9→import Combine
    10→import MatrixRustSDK
    11→import SwiftUI
    12→
    13→typealias EncryptionResetScreenViewModelType = StateStoreViewModelV2<EncryptionResetScreenViewState, EncryptionResetScreenViewAction>
    14→
    15→class EncryptionResetScreenViewModel: EncryptionResetScreenViewModelType, EncryptionResetScreenViewModelProtocol {
    16→    private let clientProxy: ClientProxyProtocol
    17→    private let userIndicatorController: UserIndicatorControllerProtocol
    18→    
    19→    private let actionsSubject: PassthroughSubject<EncryptionResetScreenViewModelAction, Never> = .init()
    20→    var actionsPublisher: AnyPublisher<EncryptionResetScreenViewModelAction, Never> {
    21→        actionsSubject.eraseToAnyPublisher()
    22→    }
    23→    
    24→    private var identityResetHandle: IdentityResetHandle?
    25→    private var passwordCancellable: AnyCancellable?
    26→
    27→    init(clientProxy: ClientProxyProtocol, userIndicatorController: UserIndicatorControllerProtocol) {
    28→        self.clientProxy = clientProxy
    29→        self.userIndicatorController = userIndicatorController
    30→        
    31→        super.init(initialViewState: EncryptionResetScreenViewState(bindings: .init()))
    32→    }
    33→    
    34→    // MARK: - Public
    35→    
    36→    override func process(viewAction: EncryptionResetScreenViewAction) {
    37→        switch viewAction {
    38→        case .reset:
    39→            state.bindings.alertInfo = .init(id: UUID(),
    40→                                             title: L10n.screenResetEncryptionConfirmationAlertTitle,
    41→                                             message: L10n.screenResetEncryptionConfirmationAlertSubtitle,
    42→                                             primaryButton: .init(title: L10n.screenResetEncryptionConfirmationAlertAction, role: .destructive) { [weak self] in
    43→                                                 guard let self else { return }
    44→                                                 Task { await self.startResetFlow() }
    45→                                             })
    46→        case .cancel:
    47→            actionsSubject.send(.cancel)
    48→        }
    49→    }
    50→    
    51→    func stop() {
    52→        Task {
    53→            await identityResetHandle?.cancel()
    54→        }
    55→    }
    56→    
    57→    // MARK: - Private
    58→    
    59→    private func startResetFlow() async {
    60→        showLoadingIndicator()
    61→        
    62→        defer {
    63→            hideLoadingIndicator()
    64→        }
    65→        
    66→        switch await clientProxy.resetIdentity() {
    67→        case .success(let handle):
    68→            // If the handle is missing then interactive authentication wasn't
    69→            // necessary and the reset proceeded as normal
    70→            guard let handle else {
    71→                actionsSubject.send(.resetFinished)
    72→                return
    73→            }
    74→            
    75→            identityResetHandle = handle
    76→            
    77→            switch handle.authType() {
    78→            case .uiaa:
    79→                let passwordPublisher = PassthroughSubject<String, Never>()
    80→                passwordCancellable = passwordPublisher.sink { [weak self] password in
    81→                    guard let self else { return }
    82→                    passwordCancellable = nil
    83→                    Task { await self.resetWith(password: password) }
    84→                }
    85→                
    86→                actionsSubject.send(.requestPassword(passwordPublisher: passwordPublisher))
    87→            case .oidc(let oidcInfo):
    88→                guard let url = URL(string: oidcInfo.approvalUrl) else {
    89→                    fatalError("Invalid URL received through identity reset handle: \(oidcInfo.approvalUrl)")
    90→                }
    91→                
    92→                hideLoadingIndicator()
    93→                
    94→                actionsSubject.send(.requestOIDCAuthorisation(url: url))
    95→                
    96→                await resetWithOIDCAuthorisation()
    97→            }
    98→        case .failure(let error):
    99→            MXLog.error("Failed resetting encryption with error \(error)")
   100→            showErrorToast()
   101→        }
   102→    }
   103→    
   104→    func resetWith(password: String) async {
   105→        guard let identityResetHandle else {
   106→            fatalError("Requested reset flow continuation without a stored handle")
   107→        }
   108→        
   109→        showLoadingIndicator()
   110→        
   111→        defer {
   112→            hideLoadingIndicator()
   113→        }
   114→        
   115→        do {
   116→            try await identityResetHandle.reset(auth: .password(passwordDetails: .init(identifier: clientProxy.userID, password: password)))
